model M version "0.2" {
type T = enum { ok }
observed case { hit: bool = false }
actor A {
  capacity 1
  capability run() -> T {
    duration fixed 3min
    result nondet { ok }
    writes hit
    finish { hit = true }
  }
  capability fast() -> T { duration fixed 1min; result nondet { ok }; writes hit; finish { hit = true } }
}
process Q { q = A.fast(); end done }
process Flow { r = A.run(); end done }
cut C { include [A] }
policy fifo tie_by case_id
scenario Light {
  arrivals fixed_every 4min during [0min, 12min)
  bounds { cases 3; live_tasks 1; clock 30min }

}
scenario Busy {
  arrivals fixed_every 1min during [0min, 3min)
  bounds { cases 3; live_tasks 1; clock 30min }

}
configuration Slow { cut C; process Flow }
configuration Fast { cut C; process Q }
verify probability reached hit == true within 4min >= 1
}

model DiffOverride version "0.2" {
  type V = enum { pass,fail }
  people [p,q]
  actor A { executors [p]; capability seed() -> V { duration fixed 1min; result nondet { pass } }; capability g(v:V) -> V { duration fixed 1min; result nondet { pass,fail } } }
  actor P { capacity 1; capability post(v:V) -> V { commits; duration fixed 1min; result nondet { pass } } }
  permit p to A.g
  process Before { seed = A.seed(); g = A.g(seed); end done }
  process After { seed = A.seed(); g = A.g(seed); if g == pass { x = P.post(g) } else { end done }; end done }
  cut C { include [A,P] }
  configuration From { cut C; process Before }
  configuration To { cut C; process After; intent { override P.post by A } }
  bounds { cases 1; live_tasks 2; clock 20min }
  verify safety no_resource_overcommit
}

model AgencySecondHalf version "0.2" {
  type Entry = enum { entry }
  type V = enum { pass, fail }
  type Ack = enum { committed }
  people [c1, a1]
  observed case { flag: bool = false }
  actor Doc { source document }
  actor Clerk { executors [c1]; capability enter() -> Entry { reads [Doc]; duration fixed 1min; result nondet { entry } } }
  actor Approver { executors [a1]; capability approve(e: Entry) -> V { duration fixed 1min; result nondet { pass, fail } } }
  actor Ledger { capacity 1; capability post(v: V) -> Ack { commits; duration fixed 1min; result nondet { committed } } }
  actor Extractor { capacity 1; capability extract() -> Entry { reads [Doc]; duration fixed 1min; result nondet { entry } } }
  process Flow { e = Clerk.enter(); v = Approver.approve(e); if v == pass {} else { end returned }; k = Ledger.post(v); end posted }
  process ToFlow { e = Extractor.extract(); v = Approver.approve(e); if v == pass {} else { end returned }; k = Ledger.post(v); w = Approver.approve(e); if flag == true { k2 = Ledger.post(w) } else {}; end posted }
  configuration From { cut Scope; process Flow }
  configuration To { cut Scope; process ToFlow; intent { retire Clerk.enter from normal_path keep fallback; add Extractor.extract reason "replace entry" } }
  cut Scope { include [Doc, Clerk, Extractor, Approver, Ledger] }
  bounds { cases 1; live_tasks 3; clock 20min }
  verify safety no_resource_overcommit
}

