model StateInvariant version "0.2" {
  type Verdict = enum { pass, fail }
  observed case { registered: bool = false; approval: optional<Verdict> }
  actor Approver {
    capacity 1
    capability approve() -> Verdict { duration fixed 2min; result nondet { pass, fail }; writes approval }
  }
  actor Ledger {
    capacity 1
    capability post() -> Verdict { duration fixed 1min; result nondet { pass }; writes registered; finish { registered = true } }
  }
  process ToFlow { j = Approver.approve(); end returned }
  process Flow { j = Approver.approve(); if approval == fail { end returned } else {}; p = Ledger.post(); end posted }
  cut C { include [Approver, Ledger] }
  configuration From { cut C; process Flow }
  configuration To { cut C; process ToFlow; intent { preserve Controls } }
  bounds { cases 1; live_tasks 2; clock 10min }

  contract Controls { invariant registered -> approval == pass }
}

model InvoiceBPR version "0.2" {
  type Entry = enum { high }
  type Verdict = enum { pass, fail }
  type Ack = enum { committed }
  type Difficulty = enum { routine, difficult }
  people [c1,c2,a1,cfo]
  observed case { entry: optional<Entry>; po, receipt, approval: optional<Verdict>; registered: bool = false }
  latent case { extraction_correct: bool = false }
  actor Invoice { source document; latent difficulty: Difficulty ~ { routine: 0.8, difficult: 0.2 } }
  actor PurchaseOrder { source record }
  actor ReceiptRecord { source record }
  kernel human_entry given [Invoice.difficulty] {
    routine -> { 0.99: high with extraction_correct = true; 0.01: high with extraction_correct = false }
    difficult -> { 0.94: high with extraction_correct = true; 0.06: high with extraction_correct = false }
  }
  kernel ai_entry given [Invoice.difficulty] {
    routine -> { 0.98: high with extraction_correct = true; 0.02: high with extraction_correct = false }
    difficult -> { 0.85: high with extraction_correct = true; 0.15: high with extraction_correct = false }
  }
  kernel po_match given [extraction_correct, Invoice.difficulty] {
    true, routine -> { 1: pass }
    true, difficult -> { 1: pass }
    false, routine -> { 0.2: pass; 0.8: fail }
    false, difficult -> { 0.5: pass; 0.5: fail }
  }
  kernel receipt_match given [extraction_correct, Invoice.difficulty] {
    true, routine -> { 1: pass }
    true, difficult -> { 1: pass }
    false, routine -> { 0.15: pass; 0.85: fail }
    false, difficult -> { 0.4: pass; 0.6: fail }
  }
  kernel approval_check given [extraction_correct, Invoice.difficulty] {
    true, routine -> { 1: pass }
    true, difficult -> { 1: pass }
    false, routine -> { 0.1: pass; 0.9: fail }
    false, difficult -> { 0.3: pass; 0.7: fail }
  }
  actor Clerk { executors [c1,c2]
    capability enter() -> Entry { reads [Invoice]; duration fixed 6min; outcomes kernel human_entry; kernel_reads latent [Invoice.difficulty]; writes [entry,extraction_correct] }
    capability match_po(e:Entry) -> Verdict { reads [PurchaseOrder]; duration fixed 3min; outcomes kernel po_match; kernel_reads latent [extraction_correct,Invoice.difficulty]; writes po }
    capability match_receipt(e:Entry) -> Verdict { reads [ReceiptRecord]; duration fixed 5min; outcomes kernel receipt_match; kernel_reads latent [extraction_correct,Invoice.difficulty]; writes receipt }
    capability recheck() -> Verdict { reads [Invoice]; duration fixed 1min; result nondet { pass,fail } }
  }
  actor Extractor { capacity 2
    capability extract() -> Entry { reads [Invoice]; duration fixed 1min; outcomes kernel ai_entry; kernel_reads latent [Invoice.difficulty]; writes [entry,extraction_correct] }
  }
  actor Approver { executors [a1]
    capability approve(e:Entry,p:Verdict,r:Verdict) -> Verdict { duration fixed 2min; outcomes kernel approval_check; kernel_reads latent [extraction_correct,Invoice.difficulty]; writes approval }
  }
  actor Ledger { capacity 1
    capability post(p:Verdict,r:Verdict,a:Verdict) -> Ack { commits; duration fixed 1min; result nondet { committed }; writes registered; finish { registered = true } }
  }
  actor Vendor { control party; standing over [end.returned] basis "invoice claim" }
  authority ApprovalGrant { basis "approval table"; grants a1 to Approver.approve; issued_by cfo }
  responsible a1 for Approver.approve
  cut InvoiceCut {
    question "One receipt of one invoice"
    include [Invoice,PurchaseOrder,ReceiptRecord,Clerk,Extractor,Approver,Ledger,Vendor]
    exclude Payment reason "separate payment domain" loses "payment errors"
    exclude VendorMaster reason "master data out of scope" loses "master data correlation"
    defer Resubmission reason "one receipt only" loses "ultimate settlement"
    defer Vendor.contest_rate reason "structure only" loses "frequency and effort"
    externality [Vendor.dispute_effort]
    reentry [contest Vendor -> Clerk.recheck, review cut quarterly by cfo]
  }
  bounds { cases 1; live_tasks 2; clock 60min }
  metrics { window 60min; currency "JPY" }
  simulation replications 1000 seed 0 confidence 0.95
  verify safety no_resource_overcommit
  verify probability reached registered == true && extraction_correct == false <= 0.001
  contract InvoiceControls {
    invariant Ledger.post.commit -> approval == pass
    invariant Ledger.post.commit -> po == pass && receipt == pass
    at_most_once Ledger.post.commit per case.id
    authority_basis Approver.approve ApprovalGrant
    separation Clerk.enter.finish, Approver.approve.finish
    response case.received -> one_of(end.posted,end.returned) by 60min after case.received otherwise unresolved
    contest Vendor on end.returned route Clerk.recheck reversible_by [a1] respond_by 7200min
  }
  process AsIsFlow {
    entry = Clerk.enter()
    poV = Clerk.match_po(entry)
    receiptV = Clerk.match_receipt(entry)
    if poV == pass && receiptV == pass {} else { end returned }
    approvalV = Approver.approve(entry,poV,receiptV)
    if approvalV == pass {} else { end returned }
    posted = Ledger.post(poV,receiptV,approvalV)
    if posted == committed { end posted } else { end exception }
  }
  process ToBePFlow {
    entry = Clerk.enter()
    fork checks { poV = Clerk.match_po(entry); receiptV = Clerk.match_receipt(entry) }
    join all checks
    if poV == pass && receiptV == pass {} else { end returned }
    approvalV = Approver.approve(entry,poV,receiptV)
    if approvalV == pass {} else { end returned }
    posted = Ledger.post(poV,receiptV,approvalV)
    if posted == committed { end posted } else { end exception }
  }
  process ToBeAFlow {
    entry = Extractor.extract()
    fork checks { poV = Clerk.match_po(entry); receiptV = Clerk.match_receipt(entry) }
    join all checks
    if poV == pass && receiptV == pass {} else { end returned }
    approvalV = Approver.approve(entry,poV,receiptV)
    if approvalV == pass {} else { end returned }
    posted = Ledger.post(poV,receiptV,approvalV)
    if posted == committed { end posted } else { end exception }
  }

  configuration AsIs { cut InvoiceCut; process AsIsFlow }
  configuration ToBeP { cut InvoiceCut; process ToBePFlow }
  configuration ToBeA { cut InvoiceCut; process ToBeAFlow }
}

model Summary version "0.2" {
  type Entry = enum { entry }
  type Verdict = enum { pass, fail }
  type Ack = enum { posted }
  actor Invoice { source document }
  actor PurchaseOrder { source record }
  actor Extract { via model "doc@v3"; capacity 1; capability make() -> Entry { reads [Invoice]; duration fixed 1min; result nondet { entry } } }
  actor Clerk { capacity 1; capability match_po(e:Entry) -> Verdict { reads [PurchaseOrder]; duration fixed 1min; result nondet { pass } } }
  actor Approver { capacity 1; capability approve(e:Entry) -> Verdict { duration fixed 1min; result nondet { pass } } }
  actor Ledger { capacity 1; capability post(p:Verdict,a:Verdict) -> Ack { commits; duration fixed 1min; result nondet { posted } } }
  process Flow {
    e = Extract.make(); p = Clerk.match_po(e); a = Approver.approve(e)
    if p == pass && a == pass {} else { end rejected }
    z = Ledger.post(p,a); end done
  }
  cut Scope { include [Invoice,PurchaseOrder,Extract,Clerk,Approver,Ledger] }

  verify reachable end.done
  verify safety no_resource_overcommit

policy fifo tie_by case_id
scenario Day { arrivals fixed [0min,0min]; horizon 12min; bounds { cases 2; live_tasks 1; clock 20min } }
metrics { window 20min; currency "JPY"; breakdown waits }
property case.Done = reached(end.done)
metric cohort.DoneRate = expected(count(case.Done)) / arrivals

configuration Left { cut Scope; process Flow }
configuration Right { cut Scope; process Flow }
}

