model ResponsibilityDiff version "0.2" {
  type Entry = enum { entry }
  type Verdict = enum { pass, fail }
  people [c1,a1,cfo]
  actor Invoice { source document }
  actor Reader { capacity 1; capability enter() -> Entry { reads [Invoice]; duration fixed 1min; result nondet { entry } } }
  actor Clerk { executors [c1]; capability recheck() -> Verdict { duration fixed 1min; result nondet { pass,fail } } }
  actor Approver {
    executors [a1]
    capability approve(e:Entry) -> Verdict { duration fixed 1min; result nondet { pass,fail } }
    capability second(e:Entry) -> Verdict { duration fixed 1min; result nondet { pass,fail } }
  }
  actor Vendor {
    control party
    standing over [end.returned] basis "invoice claim"
  }
  authority ApprovalGrant {
    basis "approval table"
    grants a1 to Approver.approve
    issued_by cfo
  }
  responsible a1 for Approver.approve
  responsible a1 for Approver.second
  process FlowA {
    entry = Reader.enter()
    approval = Approver.approve(entry)
    if approval == fail { end returned } else { end posted }
  }
  process FlowB {
    entry = Reader.enter()
    b = Approver.second(entry)
    if b == fail { end returned } else { end posted }
  }
  cut Scope { include [Invoice,Reader,Clerk,Approver,Vendor] }
  configuration A { cut Scope; process FlowA }
  configuration B { cut Scope; process FlowB }
  bounds { cases 1; live_tasks 2; clock 20min }
  verify safety no_resource_overcommit
  contract Controls {
    contest Vendor on end.returned route Clerk.recheck reversible_by [a1] respond_by 5min
  }
}

model RecordQuality version "0.2" {
 type Verdict = record { confidence: enum { pass, fail } }
 observed case { entry: optional<Verdict>; registered: bool = false }
 latent case { correct: bool = false }
 kernel K { * -> { 0.9: Verdict { confidence = pass } with correct = true; 0.02: Verdict { confidence = pass } with correct = false; 0.08: Verdict { confidence = fail } with correct = false } }
 actor A { capacity 1; capability run() -> Verdict { duration fixed 1min; outcomes kernel K; writes [entry,correct] } }
 type Ack = enum { ok }
 actor Ledger { capacity 1; capability post() -> Ack { duration fixed 1min; result nondet { ok }; writes registered; finish { registered = true } } }
 process P { v = A.run(); if v.confidence == pass { a = Ledger.post(); end posted } else { end returned } }
 cut C { include [A,Ledger] }
 bounds { cases 1; live_tasks 1; clock 10min }
 verify safety no_resource_overcommit
 verify probability reached entry.confidence == pass >= 0.92
 property case.Registered = reached(registered == true)
 property case.Wrong = reached(registered == true && correct == false)
 property case.Pass = reached(entry.confidence == pass)
 metric cohort.WrongRate = expected(count(case.Wrong)) / arrivals
 metric cohort.Conditional = expected(count(case.Wrong)) / expected(count(case.Registered))
 metric cohort.PassRate = expected(count(case.Pass)) / arrivals

metric quantile.All = quantile(0.5, case.Wrong)
metric quantile.Given = quantile(1, case.Wrong given reached)

configuration One { cut C; process P }
configuration Two { cut C; process P }
}

model Waive version "0.2" {
  type T = enum { ok, bad }
  people [p,q,issuer]
  actor Officer { executors [p]; capability release() -> T { commits; duration fixed 1min; result nondet { ok } } }
  actor B { capacity 1; capability run() -> T { duration fixed 1min; result nondet { ok } } }
  actor Wait { capacity 1; capability run() -> T { duration fixed 4min; result nondet { ok } } }
  permit [p,q] to Officer.release
  authority G { basis "registered authority"; grants [p,q] to Officer.release; issued_by issuer }
  process Flow { o = Officer.release(); w = Wait.run(); end done }
  cut C { include [Officer,B,Wait] }
  configuration A { cut C; process Flow }
  configuration BPlan { cut C; process Flow }
  bounds { cases 1; live_tasks 2; clock 20min }
  verify safety no_resource_overcommit
  contract Controls {
    response delivery: case.received -> one_of(B.run.finish) by 2min after case.received otherwise unresolved
    waive delivery on Officer.release.finish reason "registered exception" authorized_by G
  }
}

